const root = process.cwd();
try {
  const envFile = await readFile(join(root, '.env'), 'utf8');
  for (const line of envFile.split(/\r?\n/)) {
    const match = line.match(/^\s*([A-Z0-9_]+)\s*=\s*(.*?)\s*$/);
    if (match && !process.env[match[1]]) process.env[match[1]] = match[2].replace(/^['"]|['"]$/g, '');
  }
} catch { /* .env is optional; platform environment variables take priority. */ }
const port = Number(process.env.PORT || 3000);
if (!process.env.MONGODB_URI) { console.error('MONGODB_URI is not set. Add your MongoDB connection string to .env (local) or the host environment (Render).'); process.exit(1); }
const client = new MongoClient(process.env.MONGODB_URI, { appName: 'sports-world', serverSelectionTimeoutMS: 15000 });
try { await client.connect(); } catch (e) { console.error(`Could not connect to MongoDB: ${e.message}`); process.exit(1); }
const database = client.db(process.env.MONGODB_DB || 'sports_world');
const db = Object.fromEntries(['users','sessions','categories','products','product_photos','store_photos','stock_transactions','carts','cart_items','orders','order_items','store_settings','customization_templates','customization_designs','coupons','login_activity','product_views','files'].map(name => [name, database.collection(name)]));

const config = {
  shopName: 'Sports World', shopAddress: 'Shop No 12, KIIT Square, KIIT Rd, Patia, Bhubaneswar, Odisha 751024',
  ownerPhone: process.env.OWNER_PHONE_NUMBER || '',
  instagramHandle: 'sportsworld.rk',
  upiId: process.env.SHOP_UPI_ID || '',
  logo: '/assets/sports-world-logo-source.png', shopImage: 'https://images.unsplash.com/photo-1579952363873-27f3bade9f55?auto=format&fit=crop&w=1200&q=85'
};
const json = (response, status, value) => response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' }).end(JSON.stringify(value));
const error = (response, status, message) => json(response, status, { error: message });
const now = () => new Date().toISOString();
const id = () => randomBytes(16).toString('hex');
const hashToken = token => createHash('sha256').update(token).digest('hex');
// Documents are addressed by their hex `id`; MongoDB's own `_id` never leaves the server.
const one = (collection, filter, options = {}) => db[collection].findOne(filter, { ...options, projection: { _id: 0, ...options.projection } });
const all = (collection, filter = {}, options = {}) => db[collection].find(filter, { ...options, projection: { _id: 0, ...options.projection } }).toArray();
const insert = (collection, doc, options) => db[collection].insertOne({ ...doc }, options);
const lookup = async (collection, ids) => new Map((await all(collection, { id: { $in: [...new Set(ids)] } })).map(doc => [doc.id, doc]));
const duplicate = e => e?.code === 11000;
const pattern = text => new RegExp(String(text).slice(0, 100).replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i');
async function transaction(work) { const session = client.startSession(); let result; try { await session.withTransaction(async () => { result = await work(session); }); return result; } finally { await session.endSession(); } }
function csvField(value) { let text=String(value??''); if(/^[\s]*[=+\-@]/.test(text))text=`'${text}`; return `"${text.replace(/"/g,'""')}"`; }
function sendCsv(response, filename, columns, rows) { const lines=[columns.map(csvField).join(','),...rows.map(row=>columns.map(column=>csvField(row[column])).join(','))]; response.writeHead(200,{'Content-Type':'text/csv; charset=utf-8','Content-Disposition':`attachment; filename="${filename}"`,'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}).end(`\uFEFF${lines.join('\r\n')}`); }
function decodeImageData(dataUrl, maxBytes=4_000_000) { const match=String(dataUrl||'').match(/^data:(image\/(png|jpeg|webp));base64,([A-Za-z0-9+/=]+)$/);if(!match)throw new Error('Upload a PNG, JPEG, or WebP screenshot.');const bytes=Buffer.from(match[3],'base64');if(bytes.length>maxBytes)throw new Error('Image must be 4 MB or smaller.');const valid=match[2]==='png'?bytes.subarray(0,8).equals(Buffer.from('89504e470d0a1a0a','hex')):match[2]==='jpeg'?bytes[0]===0xff&&bytes[1]===0xd8&&bytes[2]===0xff:bytes.subarray(0,4).toString()==='RIFF'&&bytes.subarray(8,12).toString()==='WEBP';if(!valid)throw new Error('Image content does not match its file type.');return {bytes,extension:match[2]==='jpeg'?'jpg':match[2]}; }
// Uploaded photos, jersey previews, and payment screenshots live in the `files` collection so they survive redeploys.
const fileDoc = (image, kind) => ({ name: `${id()}.${image.extension}`, kind, content_type: image.extension === 'jpg' ? 'image/jpeg' : `image/${image.extension}`, data: image.bytes, created_at: now() });

const unique = key => ({ key, unique: true });
const indexes = {
  users: [unique({ id: 1 }), unique({ email: 1 }), { key: { created_at: -1 } }],
  sessions: [unique({ token_hash: 1 }), { key: { user_id: 1 } }, { key: { expires_at: 1 }, expireAfterSeconds: 0 }],
  categories: [unique({ id: 1 }), unique({ name: 1 })],
  products: [unique({ id: 1 }), unique({ sku: 1 }), { key: { created_at: -1 } }],
  product_photos: [unique({ id: 1 }), { key: { product_id: 1, created_at: 1 } }],
  store_photos: [unique({ id: 1 }), { key: { placement: 1, created_at: -1 } }],
  stock_transactions: [unique({ id: 1 }), { key: { created_at: -1 } }],
  carts: [unique({ id: 1 }), unique({ user_id: 1 })],
  cart_items: [unique({ id: 1 }), { key: { cart_id: 1 } }],
  orders: [unique({ id: 1 }), { key: { user_id: 1, created_at: -1 } }, { key: { created_at: -1 } }],
  order_items: [unique({ id: 1 }), { key: { order_id: 1 } }],
  store_settings: [unique({ key: 1 })],
  customization_templates: [unique({ id: 1 })],
  customization_designs: [unique({ id: 1 })],
  coupons: [unique({ id: 1 }), unique({ code: 1 })],
  login_activity: [unique({ id: 1 }), { key: { logged_at: -1 } }, { key: { user_id: 1 } }],
  product_views: [unique({ id: 1 }), unique({ user_id: 1, product_id: 1, view_date: 1 }), { key: { viewed_at: -1 } }],
  files: [unique({ name: 1 })]
};
await Promise.all(Object.entries(indexes).map(([name, specs]) => db[name].createIndexes(specs)));

async function seed() {
  if (await one('products', {})) return;
  const categories = [['Cricket','equipment'],['Football','equipment'],['Basketball','equipment'],['Badminton','equipment'],['Tennis','equipment'],['Table Tennis','equipment'],['Volleyball','equipment'],['Gym & Fitness','equipment'],['Other Sports','equipment'],['Football Jerseys','merchandise'],['Cricket Jerseys','merchandise'],['Sports T-shirts','merchandise'],['Shorts','merchandise'],['Tracksuits','merchandise'],['Caps','merchandise'],['Socks','merchandise']];
  const categoryIds = {};
  for (const [name, kind] of categories) { await db.categories.updateOne({ name }, { $setOnInsert: { id: id(), name, kind, created_at: now() } }, { upsert: true }); categoryIds[name] = (await one('categories', { name })).id; }
  const products = [
    ['Cricket Bat Starter','Cricket','equipment','Balanced English-willow style practice bat for training.','249900',12,'SW-CR-001','Sports World','/assets/sports-world-sign.png'],
    ['Match Football','Football','equipment','Durable stitched football for everyday training and matches.','89900',18,'SW-FB-001','Sports World','/assets/sports-world-sign.png'],
    ['Badminton Racket','Badminton','equipment','Lightweight racket for club and recreational play.','119900',7,'SW-BD-001','Sports World','/assets/sports-world-sign.png'],
    ['Custom Team Jersey','Football Jerseys','merchandise','Made-to-order jersey with your name and number.','79900',20,'SW-JR-001','Sports World','/assets/sports-world-logo-source.png'],
    ['Training T-shirt','Sports T-shirts','merchandise','Breathable training t-shirt. Available in selected sizes.','49900',15,'SW-TS-001','Sports World','/assets/sports-world-logo-source.png']
  ];
  await db.products.insertMany(products.map(([name, category, type, description, price, stock, sku, brand, image]) => ({ id: id(), name, category_id: categoryIds[category], type, description, price_cents: Number(price), discount_cents: null, stock, sku, brand, image, status: 'active', metadata: '{}', demo: 1, created_at: now(), updated_at: now() })));
  if (!await one('customization_templates', {})) await insert('customization_templates', { id: id(), name: 'Classic Sports Jersey', product_type: 'jersey', base_price_cents: 79900, enabled: 1, config: JSON.stringify({ printNameCents: 10000, printNumberCents: 10000, extraLogoCents: 15000 }) });
}
await seed();
if (process.env.FIRST_SUPERADMIN_EMAIL && !await one('users', { role: 'superadmin' })) { const ownerEmail=process.env.FIRST_SUPERADMIN_EMAIL.trim().toLowerCase(), existing=await one('users',{ email: ownerEmail }); if(existing)await db.users.updateOne({ id: existing.id },{ $set: { role: 'superadmin' } }); else await insert('users',{ id: id(), name: 'Store Owner', email: ownerEmail, role: 'superadmin', active: 1, created_at: now(), profile_picture: null }); }

async function body(request, limit = 6_000_000) { const chunks=[];let size=0;for await(const chunk of request){size+=chunk.length;if(size>limit)throw Object.assign(new Error('Request is too large.'),{status:413});chunks.push(chunk);}try{return chunks.length?JSON.parse(Buffer.concat(chunks).toString('utf8')):{};}catch{throw Object.assign(new Error('Invalid JSON.'),{status:400});} }
function cookie(request, name) { return (request.headers.cookie || '').split(';').map(v=>v.trim()).find(v=>v.startsWith(`${name}=`))?.slice(name.length+1); }
function safeReturnTo(value) { return typeof value==='string'&&value.startsWith('/')&&!value.startsWith('//')&&!value.includes('\\')?value:'/#home'; }
function authRedirect(returnTo, code) { const target=new URL(safeReturnTo(returnTo),'https://sports-world.invalid');target.searchParams.set('authError',code);return `${target.pathname}${target.search}${target.hash}`; }
function clearOAuthState(response) { const secure=process.env.NODE_ENV==='production'?'; Secure':'';response.setHeader('Set-Cookie',[`sw_oauth_state=; HttpOnly; SameSite=Lax; Path=/auth/google/callback; Max-Age=0${secure}`]); }
function googleOAuthReady() { return Boolean(process.env.GOOGLE_CLIENT_ID&&process.env.GOOGLE_CLIENT_SECRET&&process.env.GOOGLE_REDIRECT_URI); }
async function currentUser(request) { const token=cookie(request,'sw_session'); if (!token) return null; const session=await one('sessions',{ token_hash: hashToken(token), expires_at: { $gt: new Date() } }); const user=session&&await one('users',{ id: session.user_id }); return user?.active ? { id:user.id,name:user.name,email:user.email,role:user.role,picture:user.profile_picture??null } : null; }
async function requireUser(request,response, roles) { const user=await currentUser(request); if(!user) { error(response,401,'Please log in to continue.'); return null; } if(roles && !roles.includes(user.role)) { error(response,403,'You do not have permission for this action.'); return null; } return user; }
async function productRows(filter={}) { const products=await all('products',filter,{ sort: { created_at: -1 } }); const [categories,photos]=await Promise.all([lookup('categories',products.map(p=>p.category_id)),all('product_photos',{ product_id: { $in: products.map(p=>p.id) } },{ sort: { created_at: 1 } })]); const photosByProduct=Map.groupBy(photos,photo=>photo.product_id); return products.map(p=>({...p, category:categories.get(p.category_id)?.name??null, metadata:JSON.parse(p.metadata||'{}'), photos:(photosByProduct.get(p.id)||[]).map(photo=>photo.url)})); }
async function cartFor(user) { let cart=await one('carts',{ user_id: user.id }); if(!cart){ cart={id:id(),user_id:user.id,created_at:now(),updated_at:now()}; try { await insert('carts',cart); } catch(e) { if(!duplicate(e)) throw e; cart=await one('carts',{ user_id: user.id }); } } const items=await all('cart_items',{ cart_id: cart.id },{ sort: { _id: 1 } }); const products=await lookup('products',items.map(item=>item.product_id)); return {...cart,items:items.map(item=>{ const product=products.get(item.product_id); return {...item,name:product?.name??null,stock:product?.stock??null,status:product?.status??null,image:product?.image??null}; })}; }
function money(value) { const number=Number(value); if(!Number.isInteger(number) || number<0) throw new Error('Invalid price.'); return number; }
async function normalizeProduct(data) { if(!data.name?.trim() || !data.sku?.trim() || !data.categoryId || !data.description?.trim()) throw new Error('Name, SKU, category, and description are required.'); const category=await one('categories',{ id: String(data.categoryId) }); if(!category) throw new Error('Choose a valid category.'); return {name:data.name.trim(),sku:data.sku.trim().toUpperCase(),categoryId:category.id,type:category.kind,description:data.description.trim(),price:money(data.priceCents),discount:data.discountCents===''||data.discountCents==null?null:money(data.discountCents),stock:Number(data.stock),brand:String(data.brand||'').trim(),image:String(data.image||'').trim(),metadata:JSON.stringify(data.metadata||{})}; }
async function createSession(response,userId){ const token=randomBytes(32).toString('hex'); await insert('sessions',{ token_hash: hashToken(token), user_id: userId, expires_at: new Date(Date.now()+1000*60*60*24*14) }); const secure=process.env.NODE_ENV==='production'?'; Secure':''; const prior=response.getHeader('Set-Cookie');response.setHeader('Set-Cookie',[...(Array.isArray(prior)?prior:prior?[prior]:[]),`sw_session=${token}; HttpOnly; SameSite=Lax; Path=/; Max-Age=1209600${secure}`]); }
// Storefront listings hide archived products and the one-off products created for custom jersey designs.
async function storefrontFilter(q) { const filter={ status: 'active', sku: { $not: /^CUSTOM-/ } }; if(q){ const match=pattern(q), categoryIds=(await all('categories',{ name: match })).map(c=>c.id); filter.$or=[{ name: match },{ description: match },{ sku: match },{ category_id: { $in: categoryIds } }]; } return filter; }
async function productSearch(q) { return productRows(await storefrontFilter(q)); }

const jerseyViews=['front','back','left','right'];
function normalizeGarment(value={}) { const color=(input,fallback)=>/^#[0-9a-f]{6}$/i.test(String(input||''))?String(input).toLowerCase():fallback; const body=color(value.body,'#196b41'); return { fit:['match','training','oversized'].includes(value.fit)?value.fit:'match', pattern:['plain','stripes','pinstripes','hoops','sash','halves','chevron','fade'].includes(value.pattern)?value.pattern:'plain', body, accent:color(value.accent,'#f2f0e8'), sleeves:color(value.sleeves,body), trim:color(value.trim,'#f2f0e8') }; }
// Base jersey plus a charge for each printed side; the studio shows the same breakdown.
function customJerseyPrice(template, views) { let config={}; try { config=JSON.parse(template.config||'{}'); } catch {} const cents=(key,fallback)=>Number.isInteger(config[key])?config[key]:fallback; return template.base_price_cents+(views.front.length?cents('frontPrintCents',10000):0)+(views.back.length?cents('backPrintCents',10000):0)+(views.left.length?cents('sleevePrintCents',7500):0)+(views.right.length?cents('sleevePrintCents',7500):0); }
