async function serveFile(response, pathname) { if(/^\/uploads\/[a-f0-9]{32}\.(?:png|jpg|webp)$/.test(pathname)){const file=await db.files.findOne({ name: pathname.slice('/uploads/'.length), kind: 'upload' },{ promoteBuffers: true });if(!file)return error(response,404,'Not found');response.writeHead(200,{'Content-Type':file.content_type,'X-Content-Type-Options':'nosniff','Cache-Control':'public, max-age=31536000, immutable'}).end(file.data);return;} if(!publicFiles.has(pathname))return error(response,404,'Not found');const relative=['/','/admin-app','/admin-app/'].includes(pathname)?'index.html':pathname.slice(1);try{const file=await readFile(join(root,relative));const type=mime[extname(relative).toLowerCase()];if(!type)return error(response,404,'Not found');response.writeHead(200,{'Content-Type':type,'X-Content-Type-Options':'nosniff','Cache-Control':relative.startsWith('assets/')?'public, max-age=86400':'no-cache'}).end(file);}catch{error(response,404,'Not found');} }

